-- 3D puppet animation per exercise (see src/puppet/exercises.ts for the format).
-- Also fills in the animations of the KineAid exercises. Safe to run more than once.
alter table public.exercises add column if not exists puppet jsonb;

update public.exercises set puppet = '{"base":"hookLying","keyframes":[{"pose":{},"move":1.4,"hold":0.8},{"pose":{"pelvis":[-115,0,0],"l_hip":[0,0,2],"r_hip":[0,0,-2],"l_knee":[75,0,0],"r_knee":[75,0,0],"l_ankle":[40,0,0],"r_ankle":[40,0,0],"neck":[25,0,0]},"move":1.2,"hold":2}],"anchor":["l_sole","r_sole"],"props":[{"type":"mat"}],"view":{"az":90,"el":12},"highlight":["pelvis"]}'::jsonb where source = 'kineaid' and source_id = 'bridge';
